class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        half = n // 2
        total_sum = sum(nums)
        left_sum = 0
        count = 0

        for i in range(n):
            left_sum += nums[i]
            right_sum = total_sum - left_sum
            if i < half:
                right_sum -= nums[i]
            if left_sum > right_sum:
                count += 1
        return count

